import sys

def solve():
    import sys
    import bisect
    input = sys.stdin.read().split()
    idx = 0
    T = int(input[idx])
    idx += 1
    results = []
    for _ in range(T):
        N = int(input[idx])
        idx += 1
        A = list(map(int, input[idx:idx + N]))
        idx += N
        used = [False] * (N + 1)
        P = [-1] * N
        stack = []
        for i in range(N):
            if A[i] == 0:
                while stack and used[stack[-1]]:
                    stack.pop()
                if stack:
                    P[i] = stack[-1]
                else:
                    for j in range(1, N + 1):
                        if not used[j]:
                            P[i] = j
                            break
            else:
                j = A[i] + 1
                while stack and stack[-1] <= j:
                    stack.pop()
                if len(stack) < j:
                    P[i] = -1
                    break
                P[i] = stack[-j]
            used[P[i]] = True
            bisect.insort(stack, P[i])
        if P[i] == -1:
            results.append('-1')
        else:
            for j in range(1, N + 1):
                if not used[j]:
                    for k in range(N):
                        if P[k] == -1:
                            P[k] = j
                            used[j] = True
                            break
            results.append(' '.join(map(str, P)))
    print('\n'.join(results))

solve()
